import{_ as o,l as s,o as a,c as n,v as r,p as i,x as t,d as h,i as l,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"一致性问题引入","description":"","frontmatter":{"title":"一致性问题引入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/coherence-intro.md","filePath":"cs/coherence-intro.md","lastUpdated":1789023840000}'),p={name:"cs/coherence-intro.md"};function m(A,e,_,f,E,u){const c=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="一致性问题引入" tabindex="-1">一致性问题引入 <a class="header-anchor" href="#一致性问题引入" aria-label="Permalink to &quot;一致性问题引入&quot;">​</a></h1><div class="epigraph"><p>写回让同一块在 SRAM 与 DRAM 各有一份；再多一份 cache 或 DMA，谁手里的才算当前值，还没有协议。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/asid-pcid">上一课</a>把页表收成树，TLB 仍缓存叶项。<a href="/cs/write-back-allocate">写回与写分配</a>已经允许 cache 比下一层新。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>是两层物理介质。本课不重讲脏位怎么置。缺口是：一旦存在<strong>同一物理块的多份副本</strong>，读可能读到旧的。本课只把问题命名清楚，不引入 MESI 状态机；超标量与多核还在后面，但 DMA 与指令/数据 cache 已经够用来陈述问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单核、单数据 cache、无 DMA 时，CPU 总从自己的 cache 读，写回的不一致对程序员不可见。加入指令 cache，self-modifying 会看见旧指令。加入 DMA，设备写 DRAM 而 CPU 还握着脏行或干净旧行。后课多核只是把「另一份 cache」变成常见情况。缺口不是再加相联度，而是<strong>定义「这块的当前值在哪」以及「一份更新后别的份怎么办」</strong>。</p><p>一致性关心同一地址的副本；多地址之间的可见顺序是<a href="/cs/memory-consistency">存储一致性模型</a>，本课不提前。</p><p><span class="marginnote">Hennessy/Patterson 把 coherence 与 consistency 分开：前者单位置，后者程序序与多位置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先规定不变式：任意时刻，同一物理块的所有可读副本必须相同；若允许一份独占脏，则其他副本不得再当有效。写必须把别人的副本作废或更新。实现可以是总线窥探，可以是目录，本课都不选。</p>',9)),(a(),i(d,null,{default:t(()=>[l(c,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E5%9D%97%22%5D%20--%3E%20C1%5B%22cache%20A%20%E5%89%AF%E6%9C%AC%22%5D%0A%20%20BLK%20--%3E%20C2%5B%22cache%20B%20%E6%88%96%20DRAM%20%E6%88%96%20DMA%22%5D%0A%20%20C1%20--%3E%7C%22%E5%86%99%22%7C%20Q%5B%22%E8%B0%81%E7%AE%97%E5%BD%93%E5%89%8D%E5%80%BC%EF%BC%9F%22%5D%0A%20%20C2%20--%3E%20Q%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>软件也可以靠显式冲刷（把脏行写回再让设备读），那是把一致性推给程序员。硬件协议的动机是：共享内存编程不想每条 store 后冲刷。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>问题一旦成立，<a href="/cs/cache-miss-types">缺失分类</a>会多出一类：因为别人写而被作废，再读则缺失。这不是强制、容量、冲突能解释的。TLB 与页表同样有副本：内核改 PTE 后必须作废各核 TLB，否则翻译不一致。本课把 TLB shootdown 当作同一问题的翻译版，不写中断风暴。</p><p>精确异常与写回同时存在：提交过的 store 已经让某行变脏，一致性必须覆盖已提交状态，未提交的 store 仍可随冲刷消失。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出 Invalid/Shared/Exclusive 状态，不画嗅探事务。那是<a href="/cs/mesi-protocol">MESI</a>，且要等<a href="/cs/multicore-shared-cache">多核与共享缓存</a>把「谁」说清。也不把问题写成「多线程锁」——锁需要一致性作为前提，但锁是操作系统课。</p><p>后课默认：谈到多份 cache，先承认有一致性问题。单核教学轨迹仍可暂时假装只有一份数据 cache。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写回制造副本；第二份 cache 或 DMA 让旧值可见。</li><li>一致性：单地址上各副本如何跟上写。</li><li>协议状态机、多核互连是后课的缺口。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 多处理器 cache 一致性章。</li></ul>',9))])}const T=o(p,[["render",m]]);export{D as __pageData,T as default};
